import {mountPlanner} from './planner.mjs';
import {mountBlendModel} from './blend-ui.mjs';
import {SOURCES,GRADES,META,KEYS,LABELS,moduleOf,initialState,simulate,validate,assess} from './model.mjs';
import {mountTemperatureGuide} from './temperature-ui.mjs';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const f=(n,d=1)=>Number(n).toLocaleString('zh-CN',{minimumFractionDigits:d,maximumFractionDigits:d});
const num=n=>Number(n).toFixed(4).replace(/\.?0+$/,'');
const unit=k=>k==='C'?'%':'ppm';
const val=(k,n)=>f(n,k==='C'?3:k==='H'?2:1);
const source=id=>SOURCES.find(s=>s.id===id);
const link=id=>id?`<a class="reference-link" href="https://doi.org/${source(id).doi}" target="_blank" rel="noopener">${id} · ${source(id).year} 论文参考 ↗</a>`:'';
let state=initialState();try{const saved=JSON.parse(localStorage.getItem('steel-refining-lab-v1'));if(saved?.version===1&&saved.initial&&saved.targets&&Array.isArray(saved.modules)&&!validate(saved).length)state=saved;}catch{}
if(!state.selected&&state.modules[0])state.selected=state.modules[0].id;
let result,dragId,toastTimer,temperatureTools,plannerTools;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000);}
function persist(){try{localStorage.setItem('steel-refining-lab-v1',JSON.stringify(state));$('#saved').textContent='方案已保存于本机';}catch{$('#saved').textContent='当前浏览器无法保存';}}
function icon(type,color='#477b6a'){
 const shapes={ladle:'<path d="M15 20h34l-5 30H20z"/><path d="M12 20h40M24 8v15m8-19v19m8-15v15M20 41h24"/><path d="M26 51v5m12-5v5"/>',vacuum:'<path d="M12 17a6 6 0 0 1 6-6h28a6 6 0 0 1 6 6v38H12z"/><path d="M18 29h28l-4 20H22zM26 7v-3h12v3M33 11v12m14-5h10v10"/><circle cx="57" cy="32" r="4"/><path d="M24 24l-2-4m10 3v-5m9 6 2-4"/>',rh:'<path d="M9 30h46l-5 24H14zM18 30V12h28v18M23 31v10h6V20h7v21h6V12M18 12h28M12 46h40"/><path d="M26 35v-9m-3 3 3-3 3 3m10-5v9m-3-3 3 3 3-3"/>',converter:'<path d="M19 16h26l7 23-9 13H21L12 39zM18 16l3-7h22l3 7M16 33h32M9 27l10 8M6 24l4 3M32 5v13"/><circle cx="32" cy="57" r="3"/><path d="M19 53l-5 8m31-8 5 8"/>',soft:'<path d="M13 23h38l-6 30H19zM10 23h44M17 36h30M26 53v7m12-7v7"/><circle cx="29" cy="43" r="1.5"/><circle cx="35" cy="35" r="1.5"/><circle cx="29" cy="29" r="1.5"/><path d="M25 14c4-6 8 4 12-3"/>',wire:'<path d="M13 27h38l-5 27H18zM10 27h44M32 43V21h17V9"/><circle cx="48" cy="12" r="8"/><circle cx="48" cy="12" r="3"/><path d="M19 41h26"/>',transfer:'<path d="M14 15h36l-5 31H19zM12 15h40M11 48h43v6H11z"/><circle cx="19" cy="57" r="4"/><circle cx="46" cy="57" r="4"/><path d="M22 38h20"/>',eaf:'<path d="M12 23h40v16l-8 13H20l-8-13zM7 23h50M23 6v22m9-26v26m9-22v22M18 40h28M20 53v5m24-5v5"/><path d="m25 30 4 5-4 4m12-9-4 5 4 4"/>',cast:'<path d="M12 12h37v14H12zM18 28v8h19v15h15M24 28v3h20v15h8M10 16H6m47 0h5"/><circle cx="36" cy="56" r="3"/><circle cx="48" cy="56" r="3"/>'};
 return `<svg viewBox="0 0 64 64" fill="none" stroke="${color}" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${shapes[type]||shapes.ladle}</svg>`;
}
function inputField(label,key,value,opts={}){return `<div class="field${opts.wide?' wide':''}"><label for="f-${key}">${label}</label><input id="f-${key}" data-field="${key}" type="number" min="${opts.min??0}" max="${opts.max??9999}" step="${opts.step??1}" value="${num(value)}"><span class="unit">${opts.unit??'教学设定'}</span></div>`;}
function renderInputs(){
 $('#grade').innerHTML=Object.entries(GRADES).map(([id,g])=>`<option value="${id}">${g.name}</option>`).join('');$('#grade').value=state.grade;$('#batch').value=state.batch;
 $('#chem-inputs').innerHTML=KEYS.map(k=>`<label class="chem-row" for="initial-${k}">${LABELS[k]}<div><input id="initial-${k}" type="number" data-initial="${k}" min="0" max="${k==='C'?5:k==='H'?50:5000}" step="${k==='C'?.01:k==='H'?.1:1}" value="${num(state.initial[k])}"><span>${unit(k)}</span></div></label>`).join('');
 $('#library').innerHTML=Object.entries(META).map(([id,m])=>`<button class="library-item" data-add="${id}" ${state.modules.length>=12?'disabled':''} aria-label="添加${m.name}"><span class="mini-icon">${icon(m.type,m.accent)}</span><span><strong>${m.name}</strong><small>${m.tag}</small></span><span class="plus" aria-hidden="true">＋</span></button>`).join('');$('#module-count').textContent=`${state.modules.length} / 12`;
 $('#context-note').textContent=GRADES[state.grade].note;
}
function renderFlow(){
 const card=(m,i)=>{const meta=META[m.type];return `<span class="flow-arrow" aria-hidden="true">→</span><div class="flow-card ${state.selected===m.id?'selected':''}" data-select="${m.id}" draggable="true" role="button" tabindex="0" aria-label="编辑${meta.name}，第${i+1}工序"><span class="card-number">${String(i+1).padStart(2,'0')}</span>${icon(meta.type,meta.accent)}<strong>${meta.short}</strong><small>${f(m.time+m.overhead,0)} min</small><div class="card-controls"><button data-move="${m.id}" data-dir="-1" aria-label="前移${meta.short}" ${i===0?'disabled':''}>←</button><button data-move="${m.id}" data-dir="1" aria-label="后移${meta.short}" ${i===state.modules.length-1?'disabled':''}>→</button><button data-remove="${m.id}" aria-label="移除${meta.short}">×</button></div></div>`;};
 $('#flow').innerHTML=`<div class="flow-card static ${state.selected==='eaf'?'selected':''}" data-select="eaf" role="button" tabindex="0" aria-label="编辑电炉初炼范围">${icon('eaf','#6e837a')}<strong>EAF 初炼</strong><small>${state.includeEAF?f(state.eafTime,1)+' min':'仅作入站边界'}</small></div>${state.modules.map(card).join('')}<span class="flow-arrow" aria-hidden="true">→</span><div class="end-card">${icon('cast','#567e6d')}连铸前</div>`;
 $('#route-caption').textContent=state.modules.length?`已连接 ${state.modules.length} 个工序 · 可调整顺序`:'从左侧设备库添加第一个工序';
 const types=state.modules.map(x=>x.type),warnings=[];
 if(['SS304','SS316L'].includes(state.grade)&&!types.some(x=>['AOD','VOD'].includes(x)))warnings.push('不锈钢路线尚未配置脱碳设备。');
 if(state.grade==='GCr15'&&!types.some(x=>['VD','RH'].includes(x)))warnings.push('轴承钢示例建议比较真空处理对H的影响。');
 if(types.includes('LF')&&types.includes('AOD')&&types.indexOf('LF')<types.indexOf('AOD'))warnings.push('LF在AOD之前：后续吹氧会改变精炼条件，请检查工序顺序。');
 if(types.some(x=>['VD','RH','VOD'].includes(x))&&!types.includes('SOFT'))warnings.push('尚未加入末期软吹，可比较其对夹杂物代理量的影响。');
 if(types.filter(x=>['VD','RH','VOD'].includes(x)).length>1)warnings.push('配置多个真空工序：本工具串行累加，需核对实际必要性。');
 $('#route-warning').textContent=warnings.length?warnings.join(' '):'跨论文参数与教学假设组合；结果用于比较趋势，不代表某钢厂完整炉次。';$('#route-warning').classList.toggle('warn',!!warnings.length);
}
function renderOutcome(){
 const checks=assess(state,result),ok=checks.filter(x=>x.ok).length;
 $('#outcome').innerHTML=`<div class="summary-top"><strong>${GRADES[state.grade].name.split(' · ')[0]}</strong><p>${ok} / 5 项达到当前研究目标 · 未核算全部牌号成分</p></div>`+checks.map(a=>{const k=a.key,i=result.initial[k],out=a.value,drop=i?100*(i-out)/i:0,target=Array.isArray(a.target)?`${a.target[0]}–${a.target[1]} %`:`≤ ${a.target} ${unit(k)}`;return `<div class="metric-item"><div class="metric-line"><span class="metric-name">${LABELS[k]}</span><span class="metric-values"><b>${val(k,out)}</b><small>${unit(k)}</small></span></div><div class="metric-track ${a.ok?'':'over'}"><span style="width:${Math.min(100,Math.max(1,i?out/i*100:100))}%"></span></div><div class="metric-meta"><span>初始 ${val(k,i)} <span class="${drop>=0?'down':'up'}">${drop>=0?'↓':'↑'} ${f(Math.abs(drop),1)}%</span></span><span>${a.ok?'目标内':'待调整'} · ${target}</span></div></div>`;}).join('')+`<div class="outcome-foot">${state.modules.some(m=>m.type==='VD')?'VD的主要可视效果是脱氢；S仅在启用并满足渣钢反应条件时变化。':'指标变化由当前时间、气量和反应参数决定。'}<br>所有成分结果均为教学模型估算。</div>`;
}
function renderEditor(){
 queueMicrotask(()=>temperatureTools?.refresh());
 const m=state.modules.find(x=>x.id===state.selected);if(state.selected==='eaf'){$('#editor-source').textContent='初炼边界';$('#editor').innerHTML=`<div class="editor-body"><div class="editor-intro"><span class="mini-icon">${icon('eaf')}</span><div><strong>EAF 电炉初炼</strong><p>钢水成分从电炉出钢开始输入。</p></div></div><div class="toggle-line"><div><label for="include-eaf">将电炉计入时间和物料</label><p>时间与料耗分别来自不同论文的参考工况。</p></div><input id="include-eaf" type="checkbox" ${state.includeEAF?'checked':''}></div><div class="field"><label for="eaf-time">电炉时间（min）</label><input id="eaf-time" type="number" min="0" max="180" step=".1" value="${state.eafTime}"></div><div class="explain-box">默认39.7 min由P02图注近似推算。氧气26.5 Nm³/t、石灰及碳料来自P01的另一个钢厂，不是同一炉复现。喷碳分配和吹氧开启时长未报告。</div>${link('P01')}${link('P02')}</div>`;return;}
 if(!m){$('#editor-source').textContent='未选中';$('#editor').innerHTML='<div class="empty-editor">点击上方设备卡片，或从设备库添加一个工序。</div>';return;}
 const meta=META[m.type],row=result?.rows?.find(x=>x.id===m.id);$('#editor-source').textContent=meta.source?`${meta.source} 参考 + 估算`:'教学设定';
 let fields=inputField(['VD','VOD','RH'].includes(m.type)?'有效处理 / 保压':'工序持续时间','time',m.time,{max:180,unit:'min · 整段，不含准备',step:1})+inputField(m.type==='RH'?'提升氩气流量':'氩气总流量','gas',m.gas,{max:m.type==='AOD'?200000:3000,unit:m.type==='RH'?'m³/h · 原文体积口径':'NL/min · 本模型标准态'});
 if(['VD','VOD','RH'].includes(m.type))fields+=inputField('抽空 + 破空附加时间','overhead',m.overhead,{max:60,unit:'min · 教学设定'});
 if(['VD','VOD','RH'].includes(m.type))fields+=inputField('真空压力','pressure',m.pressure,{max:10000,unit:'Pa',min:10});
 if(['LF','AOD'].includes(m.type))fields+=inputField('石灰','lime',m.lime,{max:100,unit:'kg/t · 顶加'})+inputField('预熔精炼渣','slag',m.slag,{max:100,unit:'kg/t · 顶加'});
 if(m.type==='LF')fields+=inputField('累计通电时间','heat',m.heat,{max:180,unit:'min · 与吹气重叠'})+inputField('铝加入量','al',m.al,{step:.1,max:10,unit:'kg/t · 教学设定'})+inputField('硅锰补加量','siMn',m.siMn,{step:.1,max:100,unit:'kg/t · 不预测Mn收得率'})+inputField('硅铁补加量','feSi',m.feSi,{step:.1,max:100,unit:'kg/t · 不预测Si收得率'});
 if(['AOD','VOD'].includes(m.type))fields+=inputField('本段氧气量','oxygen',m.oxygen,{step:.5,max:100,unit:'Nm³/t · 教学设定'});
 if(m.type==='CA')fields+=inputField('包芯线整线量','wire',m.wire,{step:.05,max:5,unit:'kg/t · 不等于纯钙量'});
 if(m.type==='RH'&&m.powderEnabled)fields+=inputField('喷粉速率','powder',m.powder,{max:200,unit:'kg/min · 基准60'})+inputField('喷粉持续时间','powderTime',m.powderTime,{max:180,unit:'min · 包含于循环处理'});
 let toggle='';if(m.type==='VD')toggle=`<div class="toggle-line"><div><label for="desulf">启用渣钢协同脱硫</label><p>需前序脱氧与有效渣层；真空本身不直接脱硫。</p></div><input id="desulf" data-check="desulf" type="checkbox" ${m.desulf?'checked':''}></div>`;if(m.type==='RH')toggle=`<div class="toggle-line"><div><label for="powder-enabled">启用RH上升管喷粉</label><p>参考P09输运工况，化学脱硫效率另作假设。</p></div><input id="powder-enabled" data-check="powderEnabled" type="checkbox" ${m.powderEnabled?'checked':''}></div>`;
 let explanation={LF:'时间参考S355的34 min。默认气体分段与8+4 kg/t渣料均为教学设定；渣钢硫平衡与传质共同影响S。',VD:'P08参考：105 t、66 Pa、260 NL/min、保压18 min。抽空破空7 min及动力学常数为教学假设；只统计保压段已设置气量。',RH:'默认20 min循环为教学设定。启用喷粉后，8 min喷粉包含于循环段，载气36 m³/h与提升气分别计量。',AOD:'50 min总周期、氧气量、渣料和还原硅铁均为教学设定。P10仅研究首段脱碳10–20 min，不是全过程标定。',VOD:'本模块为教学模型；P12是AOD的316L模型，不能视作本VOD模块的直接实验依据。',SOFT:'默认15 min、50 NL/min为教学值；GCr15示例25 min参考P06。总氧变化不代表所有夹杂物均已去除。',CA:'输入的是整线质量，含钢皮和芯粉。钙处理不默认去除S或T.O；夹杂改性效果仅作定性提示。',WAIT:'时间用于等待和转运汇总；未计算温降。'}[m.type];
 const ds=row?.sDelta??0,dh=row?.hDelta??0;let effect=m.type==='VD'?`本段 H <strong>↓ ${f(dh,2)}</strong> ppm　S <strong>${Math.abs(ds)<.001?'不变':'↓ '+f(ds,1)}</strong>${Math.abs(ds)<.001?'':' ppm'}`:`本段 S <strong>${Math.abs(ds)<.001?'不变':'↓ '+f(ds,1)}</strong>${Math.abs(ds)<.001?'':' ppm'}　H <strong>${Math.abs(dh)<.001?'不变':'↓ '+f(dh,2)}</strong>${Math.abs(dh)<.001?'':' ppm'}`;
 $('#editor').innerHTML=`<div class="editor-body"><div class="editor-intro"><span class="mini-icon">${icon(meta.type,meta.accent)}</span><div><strong>${meta.name}</strong><p>${meta.desc}</p></div></div>${toggle}<div class="editor-grid">${fields}</div><div class="effect-callout">${effect}</div><div class="explain-box">${explanation}${row?.notes.length?'<br>'+esc(row.notes[0]):''}</div><details class="details-model"><summary>展开反应估算参数</summary><p>这些常数是教学设定，未从论文拟合。不是设备固有脱除率。</p><div class="editor-grid">${inputField('硫传质常数 kS','kS',m.kS,{step:.005,max:1,unit:'min⁻¹ · 可校准'})}${inputField('氢反应常数 kH','kH',m.kH,{step:.01,max:1,unit:'min⁻¹ · 可校准'})}${inputField('有效硫分配比 Ls','L',m.L,{step:10,max:1000,unit:'无量纲 · 教学设定'})}</div></details>${link(meta.source)}</div>`;
}
function renderChart(){
 const k=state.metric||'S';$('#metric-switch').innerHTML=KEYS.map(x=>`<button data-metric="${x}" class="${x===k?'active':''}" aria-label="查看${LABELS[x]}变化">${x==='O'?'T.O':x}</button>`).join('');const pts=result.points,w=650,h=180,left=47,right=25,top=18,bottom=36,range=state.targets[k],target=Array.isArray(range)?range[1]:range,max=Math.max(...pts.map(p=>p.values[k]),target,1)*1.15,min=0,maxTime=Math.max(1,result.time-(state.includeEAF?state.eafTime:0));const x=i=>left+(pts.length===1?0:(pts[i].time-pts[0].time)/maxTime)*(w-left-right),y=v=>h-bottom-(v-min)/(max-min)*(h-top-bottom);let path=pts.map((p,i)=>`${i?'L':'M'}${x(i)},${y(p.values[k])}`).join(' ');const area=path+` L${x(pts.length-1)},${h-bottom} L${left},${h-bottom}Z`;
 let grid=[0,.5,1].map(v=>{const yy=top+(h-top-bottom)*v;return `<line x1="${left}" y1="${yy}" x2="${w-right}" y2="${yy}" stroke="#e5ece8" stroke-dasharray="3 4"/><text x="${left-9}" y="${yy+3}" text-anchor="end" fill="#91a198" font-size="9">${f(max*(1-v),k==='C'?2:0)}</text>`;}).join('');
 $('#chart').innerHTML=`<div class="chart-box"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${LABELS[k]}从${val(k,result.initial[k])}变化至${val(k,result.final[k])}${unit(k)}"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#dcefe4" stop-opacity=".8"/><stop offset="100%" stop-color="#edf6f0" stop-opacity=".1"/></linearGradient></defs>${grid}<path d="${area}" fill="url(#chart-fill)"/><line x1="${left}" x2="${w-right}" y1="${y(target)}" y2="${y(target)}" stroke="#c6a77c" stroke-dasharray="4 4"/><text x="${w-right}" y="${y(target)-5}" font-size="9" text-anchor="end" fill="#b08b56">研究目标上限 ${target}</text><path d="${path}" fill="none" stroke="#287f69" stroke-width="2.4"/>${pts.map((p,i)=>`<circle cx="${x(i)}" cy="${y(p.values[k])}" r="4" fill="#fff" stroke="#287f69" stroke-width="2"/><text x="${x(i)}" y="${y(p.values[k])-10}" text-anchor="middle" font-size="10" fill="#456e59">${val(k,p.values[k])}</text>${pts.length<=7||i===0||i===pts.length-1?`<text x="${x(i)}" y="${h-10}" text-anchor="middle" font-size="9" fill="#7f9286">${esc(p.name)}</text>`:''}`).join('')}</svg><div class="chart-caption"><span>${LABELS[k]} / ${unit(k)} · 节点估算，连线仅作引导</span><span>虚线：研究目标上限</span></div></div>`;
 $('#step-effects').innerHTML=result.rows.filter(r=>r.type).map(r=>{const delta=r.before[k]-r.after[k];return `<span class="step-chip">${META[r.type].short} ${Math.abs(delta)<.0001?'—':(delta>0?'−':'+')+val(k,Math.abs(delta))+' '+unit(k)}</span>`;}).join('');
}
function renderSchedule(){
 const rows=result.rows,total=Math.max(1,result.time),gasTime=rows.filter(r=>r.gasTime!==null).reduce((n,r)=>n+r.gasTime,0),powderTime=rows.reduce((n,r)=>n+(r.powderTime||0),0);
 $('#schedule').innerHTML=`<div class="summary-numbers"><div><small>串行计划总时长</small><strong>${f(total,1)} <span>min</span></strong></div><div><small>已设置吹氩累计时间</small><strong>${f(gasTime,1)} <span>min</span></strong></div><div><small>喷粉累计开启时间</small><strong>${f(powderTime,1)} <span>min · 包含在对应工序内</span></strong></div></div><div class="gantt">${rows.map(r=>`<div class="gantt-row"><span>${esc(r.name.split(' ')[0])}</span><div class="gantt-track"><span style="left:${r.start/total*100}%;width:${r.duration/total*100}%;background:${META[r.type]?.accent||'#81958b'}"></span></div><span>${f(r.duration,1)} min</span></div>`).join('')}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>工序</th><th>开始 → 结束 / min</th><th>占用时间 / min</th><th>吹氩时间 / min</th><th>喷粉时间 / min</th><th>依据</th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${esc(r.name)}</strong></td><td>${f(r.start,1)} → ${f(r.end,1)}</td><td>${f(r.duration,1)}</td><td>${r.gasTime===null?'未报告':f(r.gasTime,1)}</td><td>${r.powderTime===null?'未报告':f(r.powderTime,1)}</td><td>${r.source||'教学'} + 估算</td></tr>`).join('')}</tbody><tfoot><tr><td colspan="2">串行汇总</td><td>${f(total,1)}</td><td>${f(gasTime,1)} *</td><td>${f(powderTime,1)}</td><td>非完整工业调度</td></tr></tfoot></table></div><p class="table-note">* 仅累计已设置的吹氩时段。电炉吹氧、抽空准备等未报告部分未计入。吹气、通电与加料相互重叠，不额外叠加到总时长。</p><h3 class="schedule-title">工序内部展开</h3><div class="table-wrap"><table class="data-table phase-table"><thead><tr><th>工序 / 子步骤</th><th>持续 / min</th><th>说明</th></tr></thead><tbody>${rows.flatMap(r=>r.phases.map(p=>`<tr><td>${esc(r.name.split(' ')[0])} / ${esc(p.name)}</td><td>${f(p.time,1)}</td><td class="wrap">${esc(p.note)}</td></tr>`)).join('')}</tbody></table></div>`;
}
function renderMaterials(){const items=result.totals;$('#materials').innerHTML=`<div class="summary-numbers"><div><small>固体辅料总量</small><strong>${f(result.solidKg/state.batch,2)} <span>kg/t</span></strong></div><div><small>标准态氩气（已计段）</small><strong>${f(result.argon/state.batch,4)} <span>Nm³/t</span></strong></div>${result.rawArgon?`<div><small>RH氩气 · 原文口径，单列</small><strong>${f(result.rawArgon/state.batch,4)} <span>m³/t</span></strong></div>`:''}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>物料 / 气体</th><th>全炉用量</th><th>吨钢用量</th><th>单位</th><th>使用工序</th><th>加入方式</th><th>依据</th></tr></thead><tbody>${items.map(a=>`<tr><td><strong>${esc(a.name)}</strong></td><td>${f(a.qty,2)}</td><td>${f(a.perTon,a.unit==='kg'?3:4)}</td><td>${esc(a.unit)}</td><td>${a.modules.map(esc).join(' / ')}</td><td class="wrap">${a.methods.map(esc).join('；')}</td><td class="wrap">${a.bases.map(esc).join('；')}</td></tr>`).join('')||'<tr><td colspan="7">当前未配置任何物料或气体。</td></tr>'}</tbody></table></div><p class="table-note">固体汇总包括造渣料、脱氧料、合金和线材，不包含废钢等主金属料、电极与耐材。未填写不代表工业消耗为零。原文m³与标准态Nm³分别统计。物料变化只影响本工具明确实现的反应，不构成完整质量/能量平衡。</p>`;}
function renderSources(){
 $('#sources').innerHTML=`<div class="source-content"><div class="model-banner"><strong>论文参数参考，不等于论文验证的设备脱除率。</strong><br>页面未运行CFD或热力学软件。工序时间参考、物料参考和教学参数可能来自不同工况；输出S、H、T.O、N、C均为简化估算。目标是比较设备作用与条件，不能据此判定钢种合格。</div><h3 style="margin-top:24px">反应是怎样估算的？</h3><div class="model-formula"><strong>S：渣钢分配 + 一阶趋近平衡</strong><br>S平衡值 =（钢中S质量 + 渣中S质量）÷（钢重 + Ls × 渣重）；S出 = S平衡 +（S入 − S平衡）× exp(−kS × t)。每段保留进入渣中的S质量，避免重复假定使用新渣。<br><strong>H：一阶脱气代理模型</strong><br>H出 = H平衡 +（H入 − H平衡）× exp(−kH × t × 气量/压力修正)。默认VD的kH=0.12 min⁻¹为教学假设，不是P08拟合值。<br><strong>VD的S变化</strong><br>默认不直接扣减S；仅当启用协同脱硫、存在有效渣层并满足脱氧代理条件时计算。该条件用T.O作简化筛选，不能代替实际溶解氧定氧。<br><strong>其他指标</strong><br>T.O为夹杂物去除代理量；未追踪粒径和形态。N暂保持不变，因此不能用本工具预测吸氮或脱氮。吹氧脱碳使用一阶模型与氧气化学计量上限，并假定80%氧利用率，未计算铬烧损。合金加入只记物料，不预测Mn、Si、Cr、Ni、Mo最终成分。</div><h3>当前研究目标 · 可自行修改</h3><p class="muted tiny">以下为学习控制值，不是产品标准全文。仅比较五项指标，不代表牌号认证。</p><div class="target-grid">${KEYS.filter(k=>k!=='C').map(k=>`<div class="field"><label for="target-${k}">${LABELS[k]}上限 / ppm</label><input id="target-${k}" data-target="${k}" type="number" min="0" max="5000" step="${k==='H'?.1:1}" value="${state.targets[k]}"></div>`).join('')}<div class="field"><label for="target-C">碳 C 上限 / %</label><input id="target-C" data-target="C" type="number" min="0" max="5" step=".01" value="${state.targets.C[1]}"></div></div><h3 style="margin-top:28px">证据索引 <span class="muted tiny">12篇 · 逐项保留适用范围</span></h3><div class="source-grid">${SOURCES.map(s=>`<article class="source-card"><span class="source-id">${s.id} / ${s.year}</span><h4>${s.title}</h4><p>${s.detail}</p><a href="https://doi.org/${s.doi}" target="_blank" rel="noopener">${s.doi} ↗</a></article>`).join('')}</div><p class="table-note">检索截至2026-10-22。近五年窗口内，当前选定证据发表于2022–2025。304/316L完整时序尚未取得，不用早期手册数据冒充近年论文。所有参数修改保存在当前浏览器本地。</p></div>`;
}
function renderTotals(){const ok=assess(state,result).filter(a=>a.ok).length;$('#totals').innerHTML=`<div class="total-item"><small>计划总时长 · 串行累计</small><strong>${f(result.time,1)} <span>min / 炉</span></strong></div><div class="total-item"><small>固体辅料 · 不含主金属料</small><strong>${f(result.solidKg/state.batch,1)} <span>kg/t</span></strong></div><div class="total-item"><small>氩气 · 标准态已计段</small><strong>${f(result.argon/state.batch,3)} <span>Nm³/t</span></strong><p>${result.rawArgon?'另有RH原文口径气量，见物料表':'未报告气量不计入'}</p></div><div class="total-item"><small>当前研究目标</small><strong>${ok}<span> / 5 项</span></strong><p>指标估算，不是牌号判定</p></div><button data-go="schedule">查看总时间表 →</button>`;}
function renderBaseline(){const b=state.baseline;if(!b){$('#baseline-result').innerHTML='';return;}const dS=result.final.S-b.final.S,dH=result.final.H-b.final.H;$('#baseline-result').innerHTML=`<div class="baseline-panel"><strong>与已保存方案对比</strong><span>${b.grade} · ${b.batch} t</span><span>时间 ${result.time-b.time>=0?'+':''}${f(result.time-b.time,1)} min</span><span>S ${dS>=0?'+':''}${f(dS,1)} ppm</span><span>H ${dH>=0?'+':''}${f(dH,2)} ppm</span>${b.grade!==state.grade||b.batch!==state.batch?'<span class="pill amber">钢种或炉容不同，请谨慎比较</span>':''}<button class="text-button" id="clear-baseline">取消对比</button></div>`;}
function changeView(view){if(view==="planner")plannerTools?.refresh();state.view=view;$$('.view').forEach(el=>el.hidden=el.id!==view+'-view');$$('.tab').forEach(el=>{el.classList.toggle('active',el.dataset.view===view);el.setAttribute('aria-current',el.dataset.view===view?'page':'false');});persist();}
function render(){renderInputs();renderFlow();result=simulate(state);$('#error').hidden=!result.errors.length;$('#error').textContent=result.errors.join('；');if(result.errors.length){$('#outcome').innerHTML='<div class="empty-editor">请修正参数后查看结果。</div>';$('#chart').innerHTML='';$('#step-effects').innerHTML='';$('#totals').innerHTML='<p>参数无效，暂不显示汇总。</p>';$('#schedule').innerHTML='';$('#materials').innerHTML='';$('#baseline-result').innerHTML='';renderEditor();changeView(state.view||'builder');return;}renderOutcome();renderEditor();renderChart();renderSchedule();renderMaterials();renderSources();renderTotals();renderBaseline();changeView(state.view||'builder');}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function exportMaterials(){if(result.errors.length)return toast('请先修正参数');const rows=[['物料','全炉用量','吨钢用量','单位','工序','方式','依据'],...result.totals.map(a=>[a.name,a.qty,a.perTon,a.unit,a.modules.join('/'),a.methods.join('；'),a.bases.join('；')])];download('精炼物料汇总.csv','\uFEFF'+rows.map(r=>r.map(x=>'"'+String(x).replace(/"/g,'""')+'"').join(',')).join('\r\n'),'text/csv;charset=utf-8');toast('物料表已导出');}
document.addEventListener('click',e=>{
 const b=e.target.closest('button,[data-select]');if(!b)return;
 if(b.dataset.add){if(state.modules.length>=12)return;const m=moduleOf(b.dataset.add),softAt=state.modules.findIndex(x=>x.type==='SOFT');if(!['SOFT','WAIT'].includes(m.type)&&softAt>=0)state.modules.splice(softAt,0,m);else state.modules.push(m);state.selected=m.id;state.view='builder';render();toast(`已添加 ${META[m.type].name}${softAt>=0&&!['SOFT','WAIT'].includes(m.type)?'，位于末期软吹之前':''}`);return;}
 if(b.dataset.remove){const idx=state.modules.findIndex(m=>m.id===b.dataset.remove);state.modules.splice(idx,1);if(state.selected===b.dataset.remove)state.selected=state.modules[Math.max(0,idx-1)]?.id||'eaf';render();return;}
 if(b.dataset.move){const i=state.modules.findIndex(m=>m.id===b.dataset.move),j=i+Number(b.dataset.dir);if(j>=0&&j<state.modules.length){[state.modules[i],state.modules[j]]=[state.modules[j],state.modules[i]];render();}return;}
 if(b.dataset.select){state.selected=b.dataset.select;renderFlow();renderEditor();persist();return;}
 if(b.dataset.view||b.dataset.go){changeView(b.dataset.view||b.dataset.go);return;}
 if(b.dataset.metric){state.metric=b.dataset.metric;renderChart();persist();return;}
 if(b.id==='reset'){state=initialState();state.selected=state.modules[0]?.id;render();toast('已重置为Q355教学方案');}
 if(b.id==='recipe'){const old={batch:state.batch,initial:state.initial,targets:state.targets,includeEAF:state.includeEAF,eafTime:state.eafTime};state={...initialState(state.grade),...old};state.selected=state.modules[0]?.id;render();toast('已载入该钢种示例流程；不是同一论文完整炉次');}
 if(b.id==='save-baseline'){if(result.errors.length)return;state.baseline={grade:state.grade,batch:state.batch,final:{...result.final},time:result.time};persist();renderBaseline();toast('已保存当前方案，可添加设备比较增量');}
 if(b.id==='clear-baseline'){state.baseline=null;renderBaseline();persist();}
 if(b.id==='export'){if(result.errors.length)return toast('请先修正参数');download('精炼流程方案.json',JSON.stringify({notice:'教学估算，未运行CFD。含可编辑参数与结果，非生产配方。',savedAt:new Date().toISOString(),state,results:result},null,2),'application/json');toast('方案与计算结果已导出');}
 if(b.id==='export-materials')exportMaterials();
 if(b.id==='show-model')changeView('sources');
 if(b.classList.contains('print-button'))window.print();
});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.phaseT||el.dataset.tconfig)return;if(el.id==='grade'){state=initialState(el.value);state.selected=state.modules[0]?.id;render();toast('已切换钢种与示例流程');return;}if(el.id==='batch')state.batch=el.valueAsNumber;if(el.dataset.initial)state.initial[el.dataset.initial]=el.valueAsNumber;if(el.dataset.target){const v=el.valueAsNumber;if(!Number.isFinite(v)||v<0||v>5000)return toast('请输入有效研究目标');if(el.dataset.target==='C'){if(v<state.targets.C[0]||v>5){el.value=state.targets.C[1];return toast('碳上限不能小于当前下限或超过5%');}state.targets.C[1]=v;}else state.targets[el.dataset.target]=v;}
 const m=state.modules.find(m=>m.id===state.selected);if(el.dataset.field&&m){m[el.dataset.field]=el.valueAsNumber;m.changed=true;}if(el.dataset.check&&m)m[el.dataset.check]=el.checked;if(el.id==='include-eaf')state.includeEAF=el.checked;if(el.id==='eaf-time'){const v=el.valueAsNumber;if(!Number.isFinite(v)||v<0||v>180)return toast('电炉时间需在0–180 min之间');state.eafTime=v;}render();});
// Recalculate on number input without replacing the active field. A blur-only
// change handler leaves stale results during typing or assistive input.
document.addEventListener('input',e=>{const el=e.target;if(el.type!=='number')return;const n=el.valueAsNumber,m=state.modules.find(x=>x.id===state.selected);if(el.id==='batch')state.batch=n;else if(el.dataset.initial)state.initial[el.dataset.initial]=n;else if(el.dataset.field&&m){m[el.dataset.field]=n;m.changed=true;}else if(el.id==='eaf-time')state.eafTime=n;else if(el.dataset.target){if(!Number.isFinite(n)||n<0||n>5000)return;if(el.dataset.target==='C'){if(n<state.targets.C[0]||n>5)return;state.targets.C[1]=n;}else state.targets[el.dataset.target]=n;}else return;result=simulate(state);$('#error').hidden=!result.errors.length;$('#error').textContent=result.errors.join('；');if(result.errors.length){$('#outcome').innerHTML='<div class="empty-editor">请修正参数后查看结果。</div>';$('#chart').innerHTML='';$('#step-effects').innerHTML='';$('#totals').innerHTML='<p>参数无效，暂不显示汇总。</p>';$('#schedule').innerHTML='';$('#materials').innerHTML='';$('#baseline-result').innerHTML='';}else{renderFlow();renderOutcome();renderChart();renderSchedule();renderMaterials();renderTotals();renderBaseline();}persist();});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-select]')){e.preventDefault();e.target.click();}});
document.addEventListener('dragstart',e=>{const el=e.target.closest('[draggable=true]');if(!el)return;dragId=el.dataset.select;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',dragId);});
document.addEventListener('dragover',e=>{if(e.target.closest('[draggable=true]'))e.preventDefault();});
document.addEventListener('drop',e=>{const target=e.target.closest('[draggable=true]');if(!target||!dragId)return;e.preventDefault();const a=state.modules.findIndex(m=>m.id===dragId),b=state.modules.findIndex(m=>m.id===target.dataset.select);if(a>=0&&b>=0&&a!==b){const [m]=state.modules.splice(a,1);state.modules.splice(b,0,m);render();toast('已调整工序顺序');}dragId=null;});
if(location.hash==='#temperature')state.view='temperature';
if(location.hash==='#blend')state.view='blend';
render();
temperatureTools=mountTemperatureGuide({getState:()=>state,persist,openStage:id=>{state.selected=id;renderFlow();renderEditor();changeView('builder');}});

plannerTools=mountPlanner({getState:()=>state,apply:s=>{state=s;state.view='builder';state.selected=state.modules[0]?.id;render();toast('已采用候选路线；可在时间安排及物料清单核对');}});
mountBlendModel({host:document.querySelector('#blend-root')});
window.addEventListener('hashchange',()=>{if(location.hash==='#blend')changeView('blend');});

